mkdir -p /tmp/ssrcheck && cat > src/__ssr_check.test.tsx <<'EOF'
import { test, expect } from 'vitest';
import { renderToString } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';

test('App renders calendar', () => {
  const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
  console.log(html.length, html.includes('No date selected'), (html.match(/gc-calendar|calendar/gi) || []).length);
  expect(html).toContain('No date selected');
  expect(html.toLowerCase()).toContain('calendar');
});
EOF
timeout 200000 npx vitest run src/__ssr_check.test.tsx 2>&1 | tail -30; rm -f src/__ssr_check.test.tsx; rm -rf /tmp/ssrcheck

